Here is the commit message:
spi: rockchip-sfc: Fix double-free in remove() callback

The driver uses devm_spi_register_controller() for registration, which
automatically unregisters the controller via devm cleanup when the
device is removed. The manual call to spi_unregister_controller() in
the remove() callback can lead to a double-free.

And to make sure controller is unregistered before DMA buffer is
unmapped, switch to use spi_register_controller() in probe().

Fixes: 8011709906d0 ("spi: rockchip-sfc: Support pm ops")
Signed-off-by: Felix Gu <ustc.gu@gmail.com>
Link: https://patch.msgid.link/20260310-sfc-v2-1-67fab04b097f@gmail.com
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The driver used `devm_spi_register_controller()` which automatically unregisters the SPI controller via devm cleanup when the device is removed, but the `remove()` callback also manually called `spi_unregister_controller()`, leading to a double-free.

Here is the patch:

 static int rockchip_sfc_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct spi_controller *host;
 	struct rockchip_sfc *sfc;
 	int ret;
 	u32 i, val;

 	host = devm_spi_alloc_host(&pdev->dev, sizeof(*sfc));
 	if (!host)
 		return -ENOMEM;

 	host->flags = SPI_CONTROLLER_HALF_DUPLEX;
 	host->mem_ops = &rockchip_sfc_mem_ops;
 	host->mem_caps = &rockchip_sfc_mem_caps;
 	host->mode_bits = SPI_TX_QUAD | SPI_TX_DUAL | SPI_RX_QUAD | SPI_RX_DUAL;
 	host->max_speed_hz = SFC_MAX_SPEED;
 	host->num_chipselect = SFC_MAX_CHIPSELECT_NUM;

 	sfc = spi_controller_get_devdata(host);
 	sfc->dev = dev;
 	sfc->host = host;

 	sfc->regbase = devm_platform_ioremap_resource(pdev, 0);
 	if (IS_ERR(sfc->regbase))
 		return PTR_ERR(sfc->regbase);

 	if (!has_acpi_companion(&pdev->dev))
 		sfc->clk = devm_clk_get(&pdev->dev, "clk_sfc");
 	if (IS_ERR(sfc->clk))
 		return dev_err_probe(&pdev->dev, PTR_ERR(sfc->clk),
 				     "Failed to get sfc interface clk\n");

 	if (!has_acpi_companion(&pdev->dev))
 		sfc->hclk = devm_clk_get(&pdev->dev, "hclk_sfc");
 	if (IS_ERR(sfc->hclk))
 		return dev_err_probe(&pdev->dev, PTR_ERR(sfc->hclk),
 				     "Failed to get sfc ahb clk\n");

 	if (has_acpi_companion(&pdev->dev)) {
 		ret = device_property_read_u32(&pdev->dev, "clock-frequency", &val);
 		if (ret)
 			return dev_err_probe(&pdev->dev, ret,
 					     "Failed to find clock-frequency in ACPI\n");
 		for (i = 0; i < SFC_MAX_CHIPSELECT_NUM; i++)
 			sfc->speed[i] = val;
 	}

 	sfc->use_dma = !of_property_read_bool(sfc->dev->of_node, "rockchip,sfc-no-dma");

 	ret = clk_prepare_enable(sfc->hclk);
 	if (ret) {
 		dev_err(&pdev->dev, "Failed to enable ahb clk\n");
 		goto err_hclk;
 	}

 	ret = clk_prepare_enable(sfc->clk);
 	if (ret) {
 		dev_err(&pdev->dev, "Failed to enable interface clk\n");
 		goto err_clk;
 	}

 	/* Find the irq */
 	ret = platform_get_irq(pdev, 0);
 	if (ret < 0)
 		goto err_irq;

 	ret = devm_request_irq(dev, ret, rockchip_sfc_irq_handler,
 			       0, pdev->name, sfc);
 	if (ret) {
 		dev_err(dev, "Failed to request irq\n");
 		goto err_irq;
 	}

 	platform_set_drvdata(pdev, sfc);

 	ret = rockchip_sfc_init(sfc);
 	if (ret)
 		goto err_irq;

 	sfc->version = rockchip_sfc_get_version(sfc);
 	sfc->max_iosize = rockchip_sfc_get_max_iosize(sfc);

 	pm_runtime_set_autosuspend_delay(dev, ROCKCHIP_AUTOSUSPEND_DELAY);
 	pm_runtime_use_autosuspend(dev);
 	pm_runtime_set_active(dev);
 	pm_runtime_enable(dev);
 	pm_runtime_get_noresume(dev);

 	if (sfc->use_dma) {
 		sfc->buffer = (u8 *)__get_free_pages(GFP_KERNEL | GFP_DMA32,
 						     get_order(sfc->max_iosize));
 		if (!sfc->buffer) {
 			ret = -ENOMEM;
 			goto err_dma;
 		}
 		sfc->dma_buffer = dma_map_single(dev, sfc->buffer,
 					    sfc->max_iosize, DMA_BIDIRECTIONAL);
 		if (dma_mapping_error(dev, sfc->dma_buffer)) {
 			ret = -ENOMEM;
 			goto err_dma_map;
 		}
 	}

-	ret = devm_spi_register_controller(dev, host);
+	ret = spi_register_controller(host);
 	if (ret)
 		goto err_register;

 	pm_runtime_put_autosuspend(dev);

 	return 0;
 err_register:
 	dma_unmap_single(dev, sfc->dma_buffer, sfc->max_iosize,
 			 DMA_BIDIRECTIONAL);
 err_dma_map:
 	free_pages((unsigned long)sfc->buffer, get_order(sfc->max_iosize));
 err_dma:
 	pm_runtime_get_sync(dev);
 	pm_runtime_put_noidle(dev);
 	pm_runtime_disable(dev);
 	pm_runtime_set_suspended(dev);
 	pm_runtime_dont_use_autosuspend(dev);
 err_irq:
 	clk_disable_unprepare(sfc->clk);
 err_clk:
 	clk_disable_unprepare(sfc->hclk);
 err_hclk:
 	return ret;
 }



